mapper.select:
SELECT event_id AS eventId,payload,created_at AS createdAt FROM sys_stat_event_inbox WHERE processed=0
AND (created_at>#{afterTime} OR (created_at=#{afterTime} AND event_id>#{afterId}))
ORDER BY created_at,event_id LIMIT #{limit}

SELECT COUNT(DISTINCT user_id) FROM sys_stat_user_day
WHERE stat_day>=#{beginDay} AND stat_day<=#{endDay}
  AND last_active_time>#{beginAt} AND last_active_time<=#{endAt}
